begin;
create table if not exists public.fasting_protocols(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,target_hours numeric not null,is_default boolean default false,created_at timestamptz default now());
create table if not exists public.fasting_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,protocol_id uuid references public.fasting_protocols(id),protocol text,target_hours numeric,started_at timestamptz not null,expected_end_at timestamptz,ended_at timestamptz,actual_hours numeric,status text not null,updated_at timestamptz default now(),deleted_at timestamptz);
create table if not exists public.routines(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,description text,created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz);
create table if not exists public.exercises(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,name text not null,category text,equipment text,muscle_group text,tracking_type text default 'reps',is_custom boolean default false,created_at timestamptz default now());
create table if not exists public.routine_exercises(id uuid primary key default gen_random_uuid(),routine_id uuid not null references public.routines(id) on delete cascade,exercise_id uuid not null references public.exercises(id),sort_order integer default 0,target_sets integer,target_reps integer);
create table if not exists public.workout_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,routine_id uuid references public.routines(id),title text,started_at timestamptz,ended_at timestamptz,duration_minutes integer,rpe numeric,status text,created_at timestamptz default now(),deleted_at timestamptz);
create table if not exists public.workout_sets(id uuid primary key default gen_random_uuid(),workout_id uuid not null references public.workout_sessions(id) on delete cascade,exercise_id uuid references public.exercises(id),set_number integer,reps numeric,weight numeric,duration_seconds integer,distance numeric,completed boolean default false);
create table if not exists public.metric_definitions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,unit text,icon text,color text,target_mode text,target_value numeric,target_min numeric,target_max numeric,graph_type text default 'line',created_at timestamptz default now());
create table if not exists public.health_readings(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,metric_id uuid references public.metric_definitions(id),recorded_at timestamptz not null,value numeric not null,context text,note text,created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz);
commit;
